import {chromium} from '@playwright/test';import fs from 'node:fs/promises';import assert from 'node:assert/strict';import {KEY,scenarioState} from '../src/model.js';
const dir='检查记录/伸缩侧栏_20261022/after';await fs.mkdir(dir,{recursive:true});
const browser=await chromium.launch({executablePath:'C:/Program Files/Google/Chrome/Application/chrome.exe',headless:true,args:['--no-proxy-server']}),p=await browser.newPage(),results=[],errors=[];p.setDefaultTimeout(7000);p.on('pageerror',e=>errors.push(e.message));
const sidebarKey='career-prototype-sidebar-v1',state=()=>p.evaluate(k=>JSON.parse(localStorage.getItem(k)),KEY);
async function load(route='/careers',width=1440,collapsed=false,lang='zh',scene='PT05'){
 await p.setViewportSize({width,height:width===390?844:1000});await p.emulateMedia({reducedMotion:'no-preference'});await p.goto('http://127.0.0.1:5184/plan');const s=scenarioState(scene.startsWith('PT')?scene:'PT05');if(!scene.startsWith('PT'))s.role=scene;
 await p.evaluate(({s,key,sidebarKey,collapsed,lang})=>{localStorage.setItem(key,JSON.stringify(s));localStorage.setItem(sidebarKey,collapsed?'collapsed':'expanded');localStorage.setItem('career-prototype-language',lang);localStorage.setItem('career-prototype-operation-guide-v1',JSON.stringify({enabled:false,neverPrompt:true}));},{s,key:KEY,sidebarKey,collapsed,lang});await p.goto('http://127.0.0.1:5184'+route);await p.locator('#main').waitFor();
}
async function settle(){await p.evaluate(async()=>{await Promise.allSettled(document.getAnimations().filter(a=>a.effect?.target?.closest?.('#main,.sidebar,.flow-progress,.app-header')).map(a=>a.finished));});}
const geometry=()=>p.evaluate(()=>{const rect=s=>{const e=document.querySelector(s);if(!e)return null;const r=e.getBoundingClientRect();return {x:r.x,y:r.y,width:r.width,height:r.height,scroll:e.scrollTop,overflow:e.scrollWidth>e.clientWidth+1};};return {sidebar:rect('#workspace-sidebar'),main:rect('#main'),flow:rect('.flow-progress'),search:rect('.workspace-search'),pageOverflow:document.documentElement.scrollWidth>innerWidth+1};});
async function shot(name){await p.screenshot({path:dir+'/'+name+'.png'});}
async function check(name,fn){try{await fn();results.push({name,status:'pass'});console.log('PASS',name);}catch(e){results.push({name,status:'fail',error:e.message});console.log('FAIL',name,e.message.slice(0,850));await shot('失败-'+results.length);}}
try{
 await check('桌面收起为图标轨道，内容及底栏得到相同空间，展开还原',async()=>{
  for(const width of [1440,1024]){await load('/plan?tab=执行',width);const before=await geometry(),business=await state();await shot(width+'-展开');await p.getByRole('button',{name:'收起侧栏',exact:true}).click();await settle();const after=await geometry();assert.equal(Math.round(after.sidebar.width),76);assert.ok(after.main.width>before.main.width+100);assert.equal(Math.round(after.main.x),76);assert.equal(Math.round(after.flow.x),76);assert.ok(after.flow.width>before.flow.width+100);assert.equal(after.pageOverflow,false);await shot(width+'-收起');assert.deepEqual(await state(),business);await p.getByRole('button',{name:'展开侧栏',exact:true}).click();await settle();assert.ok(Math.abs((await geometry()).main.width-before.main.width)<1);}
 });
 await check('图标具有名称、当前项高亮，悬停/键盘提示不裁切，点击和切换工作区可用',async()=>{
  await load('/careers',1440,true);const sidebar=p.locator('#workspace-sidebar'),career=sidebar.getByRole('link',{name:'职业探索',exact:true});assert.equal(await career.getAttribute('aria-current'),'page');await career.hover();await p.getByRole('tooltip').waitFor();assert.equal(await p.getByRole('tooltip').innerText(),'职业探索');const tip=await p.getByRole('tooltip').boundingBox();assert.ok(tip.x>=76);await shot('1440-图标提示');await career.focus();await career.press('Escape');assert.equal(await p.getByRole('tooltip').count(),0);const next=sidebar.getByRole('link',{name:'目标计划',exact:true});await next.focus();await next.press('Enter');assert.equal(new URL(p.url()).pathname,'/plan');assert.equal(await sidebar.getAttribute('data-collapsed'),'true');await sidebar.getByRole('button',{name:'切换工作区',exact:true}).click();assert.equal(await p.locator('dialog[open]').count(),1);
 });
 await check('刷新与路由保留偏好，Ctrl+反斜杠即时切换，业务数据不变',async()=>{
  await load('/careers',1440,true);const before=await state();await p.reload();assert.equal(await p.locator('#workspace-sidebar').getAttribute('data-collapsed'),'true');await p.keyboard.press('Control+Backslash');assert.equal(await p.locator('#workspace-sidebar').getAttribute('data-collapsed'),'false');assert.equal(await p.locator('#main').evaluate(e=>e.getAnimations().length),0);assert.deepEqual(await state(),before);
 });
 await check('快速反向切换可中断，正文输入和滚动不丢失',async()=>{
  await load('/plan?tab=复盘',1440);const field=p.locator('textarea[name=result]');await field.fill('保留本人草稿（合成验收）');await p.locator('#main').evaluate(e=>e.scrollTop=250);const before=await p.locator('#main').evaluate(e=>e.scrollTop);await p.getByRole('button',{name:'收起侧栏',exact:true}).click();await p.waitForTimeout(55);const middle=await p.locator('#main').evaluate(e=>({x:e.getBoundingClientRect().x,animations:e.getAnimations().length}));assert.ok(middle.animations>0);await p.getByRole('button',{name:'展开侧栏',exact:true}).click();await settle();assert.equal(await field.inputValue(),'保留本人草稿（合成验收）');assert.ok(Math.abs(await p.locator('#main').evaluate(e=>e.scrollTop)-before)<5);assert.equal(await p.locator('#workspace-sidebar').getAttribute('data-collapsed'),'false');
 });
 await check('核心功能展开适配，手机完整文字导航，英文和管理导航可用',async()=>{
  for(const [route,width,lang]of [['/app',1440,'zh'],['/assessment',1440,'zh'],['/careers?tab=企业与岗位',1440,'zh'],['/career-map',1440,'zh'],['/reports?tab=岗位简历',1440,'zh'],['/assistant',1440,'zh'],['/careers',1024,'en']]){await load(route,width,true,lang);const data=await geometry();assert.equal(data.pageOverflow,false,route);assert.equal(data.main.overflow,false,route);await shot(width+'-'+lang+'-'+encodeURIComponent(route));}
  await load('/admin/data',1440,true,'zh','data');assert.equal(await p.locator('.sidebar-links a').count(),3);await p.locator('.sidebar-links a').nth(2).click();assert.equal(new URL(p.url()).pathname,'/admin/content');await shot('1440-管理图标导航');
  await load('/careers',390,true);assert.equal(await p.locator('#workspace-sidebar').isVisible(),false);assert.equal(await p.getByRole('button',{name:'展开侧栏',exact:true}).count(),0);await p.getByRole('button',{name:'导航',exact:true}).click();assert.equal(await p.locator('#workspace-sidebar').isVisible(),true);assert.equal(await p.locator('.sidebar-links a').first().locator('.sidebar-item-label').isVisible(),true);await shot('390-完整导航');await p.locator('.sidebar-links').getByRole('link',{name:'目标计划',exact:true}).click();assert.equal(await p.locator('#workspace-sidebar').isVisible(),false);assert.equal((await geometry()).pageOverflow,false);await shot('390-正文');
 });
 await check('减少动态效果关闭空间位移，偏好保持且清理动画层',async()=>{
  await load('/careers');await p.emulateMedia({reducedMotion:'reduce'});await p.getByRole('button',{name:'收起侧栏',exact:true}).click();assert.equal(await p.locator('#main').evaluate(e=>e.getAnimations().length),0);assert.equal((await geometry()).sidebar.width,76);assert.equal(await p.locator('#main').evaluate(e=>e.style.willChange),'');
 });
}finally{await fs.writeFile(dir+'/交互验收.json',JSON.stringify({results,errors},null,2));await browser.close();}if(errors.length||results.some(r=>r.status==='fail'))process.exitCode=1;
